    t3_mask = data['option_b_ratings'].apply(lambda x: tuple(x) == (0, 0, 1, 1, 0, 0))
    p_a_t2 = 1.0 - data[t2_mask]['response'].mean()
    p_a_t3 = 1.0 - data[t3_mask]['response'].mean()
    return float(p_a_t3 - p_a_t2)

